		"":          true,
		"()[]{}":    true,
		"([{}])":    true,
		"(]":        false,
		"([)]":      false,
		"((":        false,
		"))":        false,
		"a(b[c]{d})": true,
	}
	for input, want := range cases {
		if got := IsBalanced(input); got != want {
			fmt.Printf("FALLO %q: got %v want %v\n", input, got, want)
		}
	}
	fmt.Println("ok")
}
